// PreToolUse guard: never let Claude edit generated files, third-party code or signing secrets.
import { readInput, relPath, block } from "./_common.mjs";

const input = readInput();
const tool = input.tool_name || "";
const ti = input.tool_input || {};

const SECRET = /(\.keystore|\.jks|export_credentials\.cfg)(\b|$)/i;

if (tool === "Bash") {
  const cmd = String(ti.command || "");
  if (SECRET.test(cmd)) {
    block(
      "Blocked: commands touching keystores or export_credentials.cfg are off-limits. " +
        "Release signing comes from GODOT_ANDROID_KEYSTORE_RELEASE_* env vars; ask the user to run it themselves.",
    );
  }
  process.exit(0);
}

const rawPath = String(ti.file_path || ti.notebook_path || "");
if (SECRET.test(rawPath)) block(`Blocked edit to ${rawPath}: signing secrets are never edited by Claude.`);
const rel = relPath(rawPath);
if (!rel) process.exit(0);

const rules = [
  [/^\.godot\//, ".godot/ is Godot's cache; it is regenerated by `godot --headless --import`"],
  [/^android\//, "android/ is the generated Android build template"],
  [/^addons\/gut\//, "addons/gut is third-party; update it by copying a new GUT release"],
  [/\.import$/, "*.import files are written by Godot's importer"],
  [/\.uid$/, "*.uid files are written by Godot"],
  [/^build\//, "build/ holds generated exports and screenshots"],
];
for (const [pattern, why] of rules) {
  if (pattern.test(rel)) block(`Blocked edit to ${rel}: ${why}. See CLAUDE.md "Never".`);
}
process.exit(0);
